 // Payslip HowTo (visible content mirroring HowTo JSON-LD)
 'payslip.howto.title': 'Comment simuler la fiche de paie d\'un nouveau frontalier',
 'payslip.howto.intro': 'Guide étape par étape pour simuler la fiche de paie d\'un nouveau frontalier en 2026 avec l\'impôt à la source tessinois, les déductions AVS/LPP et la comparaison du net CH vs IT.',
 'payslip.howto.step1.name': 'Saisissez le salaire brut annuel en CHF',
 'payslip.howto.step1.text': 'Saisissez le salaire brut annuel en francs suisses (CHF) tel qu\'indiqué sur le contrat de travail. Le simulateur calcule automatiquement le brut mensuel en divisant par 13 (13e mois inclus).',
 'payslip.howto.step2.name': 'Indiquez âge, état civil et enfants à charge',
 'payslip.howto.step2.text': 'Sélectionnez l\'âge (détermine le taux LPP), l\'état civil (barème A célibataire ou B marié) et le nombre d\'enfants à charge. Chaque enfant réduit l\'impôt à la source d\'environ un point de pourcentage.',
 'payslip.howto.step3.name': 'Choisissez la zone de résidence (jusqu\'à ou au-delà de 20 km)',
 'payslip.howto.step3.text': 'Indiquez si vous résidez à moins de 20 km de la frontière suisse ou au-delà. Selon le Nouvel Accord 2026, les nouveaux frontaliers dans les 20 km paient 80% d\'impôt à la source en Suisse et l\'IRPEF italien avec une franchise de 10 000 €, au-delà de 20 km la retenue suisse est de 100%.',
 'payslip.howto.step4.name': 'Vérifiez les déductions sociales suisses',
 'payslip.howto.step4.text': 'Consultez le détail des cotisations obligatoires : AVS/AI/APG (5,3%), AC chômage (1,1%), AANP accident non professionnel, IJM indemnités maladie et LPP (2e pilier, taux par tranche d\'âge 25-65).',
 'payslip.howto.step5.name': 'Visualisez la simulation de l\'impôt à la source',
 'payslip.howto.step5.text': 'Consultez l\'impôt à la source calculé selon le barème cantonal tessinois A/B/C/H 2026, avec le pourcentage et le montant en CHF sur une base mensuelle.',
 'payslip.howto.step6.name': 'Comparez le net suisse avec le net italien en euros',
 'payslip.howto.step6.text': 'Comparez le net suisse au net italien en tenant compte de l\'IRPEF et du crédit d\'impôt : c\'est le montant qui reste effectivement à un nouveau frontalier en 2026.',
 'payslip.howto.step7.name': 'Exportez la fiche de paie en PDF',
 'payslip.howto.step7.text': 'Téléchargez le récapitulatif de la simulation en PDF avec toutes les déductions AVS, AC, AANP, IJM, LPP et l\'impôt à la source : utile pour la comparer à la vraie fiche de paie remise par l\'employeur.',

 // Payslip FAQ (visible content mirroring FAQPage JSON-LD)
 'payslip.faq.title': 'FAQ — Fiche de paie du frontalier',
 'payslip.faq.q1.q': 'Qu\'est-ce que le Nouvel Accord frontaliers 2026 ?',
 'payslip.faq.q1.a': 'Le nouvel accord fiscal Italie-Suisse (en vigueur depuis 2024 et pleinement appliqué en 2026) distingue les "anciens" et les "nouveaux" frontaliers. Les nouveaux frontaliers (embauchés à partir du 17/07/2023) qui résident dans les 20 km de la frontière paient 80% d\'impôt à la source en Suisse et déclarent leurs revenus en Italie avec une franchise de 10 000 € et un crédit d\'impôt. Au-delà de 20 km, la retenue suisse est de 100%.',
 'payslip.faq.q2.q': 'Quand est-on considéré comme "nouveau frontalier" ?',
 'payslip.faq.q2.a': 'On est nouveau frontalier si le contrat de travail suisse a été signé à partir du 17 juillet 2023. Ceux qui étaient embauchés avant cette date restent "anciens frontaliers" jusqu\'au 31 décembre 2033 (période transitoire), avec une imposition uniquement en Suisse à 100% et des ristournes aux communes frontalières italiennes.',
 'payslip.faq.q3.q': 'Comment l\'impôt à la source est-il calculé au Tessin en 2026 ?',
 'payslip.faq.q3.a': 'L\'impôt à la source tessinois est appliqué par l\'employeur selon le barème cantonal : A (célibataire, sans enfants), B (marié, revenu unique), C (marié, double revenu) et H (famille monoparentale). Le taux dépend du revenu mensuel brut et varie d\'environ 2% (CHF 3 000/mois) à 16% (au-delà de CHF 15 000/mois). Chaque enfant à charge réduit le taux d\'environ un point de pourcentage.',
 'payslip.faq.q4.q': 'Qu\'est-ce qui change si j\'habite au-delà de 20 km de la frontière suisse ?',
 'payslip.faq.q4.a': 'Les nouveaux frontaliers qui résident au-delà de 20 km de la frontière suisse perdent le statut fiscal de frontalier selon le Nouvel Accord : ils paient 100% d\'impôt à la source en Suisse (comme les résidents sans ristourne) et déclarent le revenu en Italie avec crédit d\'impôt intégral pour éviter la double imposition. La franchise de 10 000 € ne s\'applique pas dans ce cas.',
 'payslip.faq.q5.q': 'Les cotisations AVS et LPP sont-elles déductibles en Italie ?',
 'payslip.faq.q5.a': 'Oui. Les cotisations suisses obligatoires AVS/AI/APG (5,3%) et LPP (2e pilier) retenues en Suisse sont déductibles du revenu imposable IRPEF des nouveaux frontaliers dans la déclaration fiscale italienne, ce qui réduit la base imposable italienne. Conservez le certificat de salaire annuel suisse (Lohnausweis) pour votre comptable.',
 'payslip.faq.q6.q': 'Puis-je utiliser le simulateur même avec un permis B ?',
 'payslip.faq.q6.a': 'Oui. Le simulateur de fiche de paie calcule les déductions sociales (AVS, AC, AANP, IJM, LPP) et l\'impôt à la source tessinois : ce sont les mêmes rubriques qu\'on trouve sur la fiche de paie d\'un titulaire de permis B travaillant au Tessin. Toutefois, avec un permis B le régime fiscal spécial du frontalier (crédit d\'impôt italien) ne s\'applique pas : le net CHF est votre vrai net. Pour une comparaison fiscale G vs B, utilisez le comparateur dédié.',
 'payslip.faq.q7.q': 'L\'impôt à la source est-il définitif ou puis-je récupérer une partie via la TDR ?',
 'payslip.faq.q7.a': 'L\'impôt à la source tessinois peut être rectifié via la TDR (Tariffa Doganale Ridotta) avant le 31 mars de l\'année suivante. Les déductions admises incluent les frais de transport (max CHF 3 200), les repas hors domicile, les cotisations au 3e pilier (max CHF 7 258 en 2026), les frais médicaux et les pensions alimentaires. Le remboursement est crédité directement sur votre compte bancaire.',
 'payslip.faq.q8.q': 'Le simulateur inclut-il le 13e mois et les allocations familiales ?',
 'payslip.faq.q8.a': 'Le salaire brut annuel saisi inclut déjà le 13e mois (divisé par 13 pour obtenir le brut mensuel). Les allocations familiales cantonales (environ CHF 200-300 par mois et par enfant au Tessin) ne sont pas incluses dans la simulation car elles ne sont pas soumises aux cotisations sociales ni à l\'impôt à la source : ajoutez-les au net calculé.',

