 'salaryCompare.canton': 'Canton',
 'salaryCompare.cantonAll': 'Suisse (moyenne nationale)',
 'salaryCompare.cantonNetTitle': 'Salaire net estimé par canton (CH)',
 'salaryCompare.cantonNetDesc': 'Estimation du salaire net suisse si le même profil travaillait dans un autre canton, basée sur les niveaux salariaux régionaux de l\'OFS (Office fédéral de la statistique).',
 'salaryCompare.cantonNetDisclaimer': 'Attention : il s\'agit d\'une ESTIMATION, pas d\'un calcul fiscal officiel. Le brut par canton reflète le niveau salarial moyen régional (données OFS) ; le net utilise le taux de charge fiscale réel du chef-lieu de chaque canton (données officielles ESTV/AFC, personne seule sans enfant, année fiscale 2024) et reflète donc les véritables différences de charge fiscale cantonale/communale — mais ne tient pas compte de votre situation personnelle (état civil, enfants, déductions, commune exacte de résidence). Pour une estimation fiscale précise, consultez le calculateur officiel de votre canton de travail.',
 'salaryCompare.cantonNetColGross': 'Brut estimé',
 'salaryCompare.cantonNetColNet': 'Net estimé',
 'salaryCompare.cantonNetComuneNote': 'Vous cherchez une estimation pour votre commune de résidence en Italie ?',
 'salaryCompare.cantonNetComuneLink': 'Utiliser la carte des communes frontalières',
 'salaryCompare.salaryRange': 'Fourchette salariale',
 'salaryCompare.median': 'Médian',
 'salaryCompare.professions': 'Professions',
 'salaryCompare.totalSectors': 'secteurs analysés',
 'salaryCompare.totalProfessions': 'professions analysées',
 'salaryCompare.methodology': 'Méthodologie & Sources de Données',
 'salaryCompare.methodologyText1': 'Les données salariales sont basées sur l\'Enquête suisse sur la structure des salaires (ESS) de l\'Office fédéral de la statistique (OFS), complétées par des données du SECO, des portails d\'emploi (jobs.ch, Michael Page) et des estimations de marché 2024-2025. Les salaires suisses sont spécifiquement ajustés pour le Canton du Tessin, qui affiche en moyenne 10-15% de moins que la médiane nationale.',
 'salaryCompare.methodologyText2': 'Pour l\'Italie, les données proviennent de l\'ISTAT, Glassdoor et Indeed, avec un focus sur les régions frontalières (Lombardie, Piémont, Ligurie). Les calculs nets incluent les déductions sociales suisses (AVS/AI/APG 5.3%, AC 1.1%, LAA 0.7%, IJM 0.8%, LPP moyenne), l\'impôt à la source tessinois et pour l\'Italie l\'IRPEF 2026, les surtaxes régionales et les cotisations INPS.',
 'salaryCompare.methodologyText3': 'Les fourchettes salariales (minimum-médian-maximum) reflètent la variabilité due à la taille de l\'entreprise, l\'expérience spécifique, les certifications et la capacité de négociation. La Parité de Pouvoir d\'Achat (PPA) est calculée avec le facteur 0.65, tenant compte du coût de la vie significativement plus élevé en Suisse.',
 'salaryCompare.faqTitle': 'Questions Fréquentes sur les Salaires',
 'salaryCompare.faq1Q': 'Quels sont les salaires moyens au Tessin en 2026 ?',
 'salaryCompare.faq1A': 'Le salaire médian au Tessin varie de CHF 48.000-55.000 pour les postes débutants dans le commerce/hôtellerie jusqu\'à CHF 125.000-200.000+ pour les postes seniors dans la finance, la pharma et l\'IT. Le Tessin a les salaires les plus bas de Suisse mais ils restent 2-3 fois supérieurs à l\'Italie.',
 'salaryCompare.faq2Q': 'Combien gagne un informaticien frontalier en Suisse ?',
 'salaryCompare.faq2A': 'Un développeur logiciel frontalier au Tessin gagne en moyenne CHF 72.000 brut en tant que junior (0-3 ans), CHF 95.000 en mid-level (3-7 ans) et CHF 125.000+ en senior (7+ ans). Après impôt à la source et cotisations sociales, le net junior est d\'environ CHF 58.000 et le senior environ CHF 93.000.',
 'salaryCompare.faq3Q': 'Être frontalier est-il financièrement intéressant ?',
 'salaryCompare.faq3A': 'Dans la plupart des secteurs, les frontaliers gagnent 100% à 200% de plus que pour un emploi équivalent en Italie, même en tenant compte des frais de transport et des impôts. Cependant, en appliquant la Parité de Pouvoir d\'Achat (PPA), l\'avantage se réduit à 30-80% car le coût de la vie suisse est beaucoup plus élevé.',
 'salaryCompare.faq4Q': 'Comment les salaires des frontaliers sont-ils imposés ?',
 'salaryCompare.faq4A': 'Les frontaliers avec permis G paient l\'impôt à la source dans le Canton du Tessin (3% à 18% selon le revenu), plus les cotisations sociales suisses (AVS, AC, LAA, IJM, LPP). Avec le Nouvel Accord 2026, les nouveaux frontaliers paient 80% des impôts en Suisse et une part en Italie avec une franchise de €10.000.',
 'salaryCompare.faq5Q': 'Quels secteurs paient le plus au Tessin ?',
 'salaryCompare.faq5A': 'Les secteurs les mieux rémunérés au Tessin sont : Finance & Banques (médiane senior CHF 145.000), Pharmaceutique (CHF 135.000), Conseil (CHF 150.000) et IT & Software (CHF 125.000). L\'hôtellerie-restauration et le commerce offrent les salaires les plus bas (CHF 68.000-72.000 senior).',
