 'jobBoard.assisted.review.fit.partialTitle': "Certaines exigences de l’annonce ne ressortent pas de votre CV",
 'jobBoard.assisted.review.fit.partialBody': "La candidature part quand même. Nous vous le disons avant l’envoi, pour que vous décidiez : si vous les remplissez, écrivez-le dans les réponses ci-dessous ou demandez-nous une modification.",
 'jobBoard.assisted.review.fit.lowTitle': "Votre profil ne couvre pas une exigence indispensable de l’annonce",
 'jobBoard.assisted.review.fit.lowBody': "L’entreprise pourrait écarter la candidature pour cette raison. Vous pouvez l’envoyer quand même : si vous remplissez l’exigence et que le CV ne le montre pas, écrivez-le dans les réponses ci-dessous ou demandez-nous une modification.",
 'jobBoard.assisted.review.fit.farTitle': "Votre profil semble éloigné de ce que demande l’annonce",
 'jobBoard.assisted.review.fit.farBody': "L’entreprise pourrait écarter la candidature. Vous pouvez l’envoyer quand même : si le CV ne montre pas tout ce que vous savez faire, écrivez-le dans les réponses ci-dessous ou demandez-nous une modification.",
 'jobBoard.assisted.review.fit.partialBodyEdit': "La candidature part quand même. Nous vous le disons avant l’envoi, pour que vous décidiez : si vous les remplissez, écrivez-le dans la lettre avec « Modifier » ou demandez-nous une nouvelle version avec « Demander des modifications ».",
 'jobBoard.assisted.review.fit.lowBodyEdit': "L’entreprise pourrait écarter la candidature pour cette raison. Vous pouvez l’envoyer quand même : si vous remplissez l’exigence et que le CV ne le montre pas, écrivez-le dans la lettre avec « Modifier » ou demandez-nous une nouvelle version avec « Demander des modifications ».",
 'jobBoard.assisted.review.fit.farBodyEdit': "L’entreprise pourrait écarter la candidature. Vous pouvez l’envoyer quand même : si le CV ne montre pas tout ce que vous savez faire, écrivez-le dans la lettre avec « Modifier » ou demandez-nous une nouvelle version avec « Demander des modifications ».",
