 'jobBoard.assisted.review.editIntroEmail': "Corrigez la lettre, l’e-mail à l’employeur et vos données. À l’enregistrement, nous mettons à jour les PDF de la lettre et du CV adapté ; ensuite vous approuvez comme d’habitude.",
 'jobBoard.assisted.review.letterLabel': "Texte de la lettre",
