 'jobBoard.assisted.review.lockedQuestion': "Cela se modifie dans la question ci-dessus.",
 'jobBoard.assisted.review.permitRule': "Le CV ne contient que des faits : votre nationalité et le permis que vous avez aujourd’hui, jamais un « permis à demander », car l’octroi dépend du contrat de travail et du canton.",
 'jobBoard.assisted.review.saveEdits': "Enregistrer les modifications",
 'jobBoard.assisted.review.cancelEdits': "Annuler",
 'jobBoard.assisted.review.editsSaved': "Modifications enregistrées : la candidature part avec votre texte.",
