 'jobBoard.assisted.review.textTooShort': "Le texte est trop court.",
 'jobBoard.assisted.review.textTooLong': "Le texte est trop long.",
 'jobBoard.assisted.review.letterTitle': "Lettre de motivation",
 'jobBoard.assisted.review.letterPdf': "Télécharger le PDF",
 'jobBoard.assisted.review.cvTitle': "Le CV que nous envoyons",
 'jobBoard.assisted.review.cvPdf': "Ouvrir le CV adapté",
 'jobBoard.assisted.review.cvIntro': "Nous avons réorganisé votre CV pour cette annonce, avec les mots de l’employeur : aucune donnée nouvelle, seulement ce que votre CV contient déjà et ce que vous indiquez sur cette page. Vérifiez-le : si vous préférez, nous envoyons votre CV original.",
 'jobBoard.assisted.review.cvPermitOmitted': "Le permis G ne figure pas dans le CV : nous ne l’indiquons qu’à côté d’une nationalité de l’UE ou de l’AELE figurant dans vos données, car pour les ressortissants d’autres États il est lié à un employeur et à une zone frontalière.",
 'jobBoard.assisted.review.cvPersonalDataNote': "Le permis, la nationalité et la date de naissance indiqués sur cette page ne figurent que dans le CV adapté : votre CV original reprend ce que contient votre fichier.",
 'jobBoard.assisted.review.cvPersonalDataNoteInplace': "Le permis, la nationalité et la date de naissance indiqués sur cette page ne figurent que dans le CV adapté : votre CV original et le fichier Word avec les lignes adaptées reprennent ce que contient votre fichier.",
 'jobBoard.assisted.review.cvAts': "Mots-clés de l’annonce trouvés : {before} % dans votre CV, {after} % dans le CV adapté.",
