 'jobBoard.assisted.review.cvInplaceNeedsCheck': "Votre fichier Word n'est plus proposé : les lignes modifiées pourraient décaler la mise en page et nous ne pouvons pas recompter les pages ici. Il redevient disponible si vous remettez les lignes adaptées ; en attendant, vous pouvez envoyer le CV adapté ou votre CV d'origine.",
 'jobBoard.assisted.review.wordCopyLetter': "Copie Word de la lettre, à conserver et modifier",
 'jobBoard.assisted.review.wordCopyCv': "Copie Word du CV, à conserver et modifier",
 'jobBoard.assisted.review.wordCopyNote': "Les copies Word sont pour vous, à conserver et modifier : ce ne sont jamais les fichiers envoyés à l’entreprise.",
 'jobBoard.assisted.review.wordCopyNoPhoto': "La copie Word du CV ne contient pas la photo : vous pouvez l’ajouter vous-même dans Word.",
 'jobBoard.assisted.review.cvChangesTitle': "Ce que nous avons changé dans votre CV",
