 'jobBoard.assisted.review.error.invalid_cv_choices': "Vérifiez les lignes écrites par vous : elles ne peuvent être ni vides ni dépasser 300 caractères.",
 'jobBoard.assisted.review.photoTitle': "Photo dans le CV (facultative)",
 'jobBoard.assisted.review.photoAdviceRecommended': "En Suisse alémanique, la photo dans le CV est courante, mais pas obligatoire. Si vous le souhaitez, ajoutez-en une : fond neutre, JPG ou PNG, 2 Mo au maximum.",
