 'tfr.badge': 'Calculateur TFR / Indemnité',
 'tfr.title': 'TFR et indemnité de licenciement pour frontaliers : Suisse vs Italie',
 'tfr.subtitle': 'En Suisse, le TFR n\'existe pas. Découvrez ce qui le remplace et comparez le 2e pilier (LPP) avec le TFR italien sur N années de cotisation.',
 'tfr.footerLink': 'TFR / Indemnité',
