 'tfr.noTfrTitle': 'En Suisse, le TFR (indemnité) n\'existe pas !',
 'tfr.noTfrText': 'Contrairement à l\'Italie, la Suisse ne prévoit pas de Trattamento di Fine Rapporto (TFR/indemnité de fin de service). Aucun montant n\'est mis de côté par l\'employeur à la fin du contrat. L\'équivalent est le 2e pilier (LPP/BVG) : une cotisation obligatoire de prévoyance professionnelle, gérée par les caisses de pension et restituée sous forme de rente ou de capital à la retraite.',
 'tfr.whatReplacesTitle': 'TFR italien vs 2e pilier suisse (LPP)',
