 'tfr.tableLppTotal': 'LPP total',
 'tfr.keyDifferencesTitle': 'Différences clés : TFR vs LPP',
 'tfr.diffAccessTitle': 'Accès aux fonds',
 'tfr.diffAccessTfr': 'Versé à la fin du contrat. Avance possible (70%) pour résidence ou frais médicaux.',
 'tfr.diffAccessLpp': 'Disponible à la retraite (65). Retrait anticipé pour résidence principale, activité indépendante ou départ définitif de Suisse.',
 'tfr.diffTaxTitle': 'Fiscalité',
 'tfr.diffTaxTfr': 'Imposition séparée avec taux moyen des 5 dernières années. Généralement favorable.',
 'tfr.diffTaxLpp': 'Pour les frontaliers rentrant en Italie : impôt à la source suisse réduit sur le capital, puis imposition italienne à 5% (rente) ou séparée (capital).',
 'tfr.diffReturnTitle': 'Rendement',
 'tfr.diffReturnTfr': 'Revalorisation fixe : 1,5% + 75% inflation ISTAT. Faible rendement réel en période de faible inflation.',
 'tfr.diffReturnLpp': 'Minimum LPP 1,25% (2026). Les meilleures caisses appliquent jusqu\'à 3-4%. Le capital est investi sur les marchés financiers.',
 'tfr.diffFrontaliereTitle': 'Ce qui se passe pour les frontaliers',
 'tfr.diffFrontaliereText1': 'Les frontaliers avec permis G accumulent de la LPP suisse (2e pilier). En quittant définitivement la Suisse, ils peuvent réclamer le capital de la partie obligatoire (prestation de libre passage). La partie surobligatoire est transférée sur un compte de libre passage.',
 'tfr.diffFrontaliereText2': 'Vous ne perdez pas le "TFR" car le TFR n\'existe pas en Suisse — le 2e pilier est le mécanisme équivalent, souvent avec des montants supérieurs au TFR italien.',
 'tfr.faqTitle': 'Questions fréquentes',
 'tfr.faq1Q': 'Est-ce que je perds le TFR en travaillant en Suisse ?',
 'tfr.faq1A': 'Non, car le TFR n\'existe pas en Suisse. À sa place, il y a le 2e pilier (LPP/BVG), une prévoyance professionnelle obligatoire. Les cotisations sont conservées par la caisse de pension de votre employeur et restituées sous forme de rente ou de capital à la retraite ou en quittant définitivement la Suisse.',
 'tfr.faq2Q': 'Puis-je récupérer le 2e pilier si je retourne en Italie ?',
 'tfr.faq2A': 'Oui. Si vous quittez définitivement la Suisse, vous pouvez réclamer la partie obligatoire du 2e pilier. La partie surobligatoire est transférée sur un compte de libre passage. En retournant dans un pays UE/AELE, la partie obligatoire reste bloquée jusqu\'à la retraite ; la partie surobligatoire peut être versée en espèces.',
 'tfr.faq3Q': 'Le 2e pilier suisse est-il plus avantageux que le TFR italien ?',
 'tfr.faq3A': 'Cela dépend du salaire, de l\'âge et de la durée d\'emploi. En général, pour des salaires moyens-élevés et de longues carrières en Suisse, le 2e pilier accumule plus que le TFR italien, car les cotisations sont proportionnellement plus élevées (7-18% vs 7,4% pour le TFR). Utilisez le simulateur ci-dessus pour votre cas spécifique.',
 'tfr.faq4Q': 'Comment le TFR italien est-il calculé ?',
 'tfr.faq4A': 'Le TFR italien est calculé en divisant le salaire brut annuel (RAL) par 13,5. La provision annuelle est revalorisée avec la formule : 1,5% fixe + 75% de l\'inflation ISTAT. Le TFR est versé à la fin de la relation de travail (démission, licenciement, retraite).',
 'tfr.faq5Q': 'Comment fonctionne le calcul LPP pour les frontaliers ?',
 'tfr.faq5A': 'Les cotisations LPP sont calculées sur le salaire coordonné (salaire brut moins la déduction de coordination de CHF 26 460, jusqu\'à un maximum de CHF 90 720). Le taux varie avec l\'âge : 7% (25-34), 10% (35-44), 15% (45-54), 18% (55-65). La cotisation est répartie à parts égales entre employeur et employé.',
 'tfr.relatedTitle': 'Outils connexes',
 'tfr.linkPension': 'Planificateur de retraite',
 'tfr.linkPillar3': 'Simulateur 3e pilier',
 'tfr.linkPayslip': 'Simulateur de fiche de paie',
 'tfr.disclaimer': 'Les calculs sont indicatifs et basés sur les paramètres légaux 2026 (taux LPP 1,25%, déduction de coordination CHF 26 460). Pour le TFR, la formule légale est utilisée (brut/13,5 + revalorisation). Les résultats ne constituent pas un conseil financier ou de prévoyance. Consultez un expert pour votre situation spécifique.',

